"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[4963],{23880(e){e.exports=JSON.parse('{"ko_kr":{"Nechronica":{"critical":"\ub300\uc131\uacf5","fumble":"\ub300\uc2e4\ud328","break_all_parts":"\uc0ac\uc6a9\ud30c\uce20 \uc804\ubd80 \uc190\uc2e4","hit_location":{"table":["\ubc29\uc5b4\uce21 \uc784\uc758","\ub2e4\ub9ac\uff08\uc5c6\uc73c\uba74 \uacf5\uaca9\uce21 \uc784\uc758\uff09","\ubab8\ud1b5\uff08\uc5c6\uc73c\uba74 \uacf5\uaca9\uce21 \uc784\uc758\uff09","\ud314\uff08\uc5c6\uc73c\uba74 \uacf5\uaca9\uce21 \uc784\uc758\uff09","\uba38\ub9ac\uff08\uc5c6\uc73c\uba74 \uacf5\uaca9\uce21 \uc784\uc758\uff09","\uacf5\uaca9\uce21 \uc784\uc758"],"additional_damage":"(\ucd94\uac00 \ub370\ubbf8\uc9c0%{damage})"},"table":{"NM":{"name":"\uc790\ub9e4\uc5d0 \ub300\ud55c \ubbf8\ub828\ud45c","type":"1D10","items":["\u3010\ud610\uc624\u3011[\ubc1c\uad11:\uc801\ub300\uc778\uc2dd]\uc804\ud22c \ub3d9\uc548 \uc801\uc5d0\uac8c \uba85\uc911\ud558\uc9c0 \uc54a\uc740 \uacf5\uaca9\uc740 \ubaa8\ub450, \uc0ac\uc815 \uac70\ub9ac \ub0b4\uc5d0 \uc788\ub2e4\uba74 \ud610\uc624\uc758 \ub300\uc0c1\uc5d0\uac8c \uba85\uc911\ud55c\ub2e4(\ubc29\uc5b4 \uce21 \uc784\uc758).","\u3010\ub3c5\uc810\u3011[\ubc1c\uad11:\ub3c5\uc810\ucda9\ub3d9]\uc804\ud22c \uc2dc\uc791 \uc2dc\uc640 \uc885\ub8cc \uc2dc \uac01\uac01 1\uac1c\uc529, \ub300\uc0c1\uc740 \ud30c\uce20\ub97c \uc120\ud0dd\ud558\uc5ec \uc190\uc0c1\uc2dc\ud0a8\ub2e4.","\u3010\uc758\uc874\u3011[\ubc1c\uad11:\uc720\uc544\ud1f4\ud589]\ucd5c\ub300 \ud589\ub3d9\uce58\uac00 \uac10\uc18c\ud55c\ub2e4(-2).","\u3010\uc9d1\ucc29\u3011[\ubc1c\uad11:\ucd94\uc801\uac10\uc2dc]\uc804\ud22c \uc2dc\uc791 \uc2dc\uc640 \uc885\ub8cc \uc2dc \uac01\uac01 1\uac1c\uc529, \ub300\uc0c1\uc740 \ub2f9\uc2e0\uc5d0 \ub300\ud55c \ubbf8\ub828\uc5d0 \uad11\uae30\uc810\uc744 \uc5bb\ub294\ub2e4.","\u3010\uc5f0\uc2ec\u3011[\ubc1c\uad11:\uc790\ud574\ud589\ub3d9]\uc804\ud22c \uc2dc\uc791 \uc2dc\uc640 \uc885\ub8cc \uc2dc \uac01\uac01 1\uac1c\uc529, \ub2f9\uc2e0\uc740 \ud30c\uce20\ub97c \uc120\ud0dd\ud574 \uc190\uc0c1\uc2dc\ud0a8\ub2e4.","\u3010\ub300\ud56d\u3011[\ubc1c\uad11:\uacfc\uc789\uacbd\uc7c1]\uc804\ud22c \uc2dc\uc791 \uc2dc\uc640 \uc885\ub8cc \uc2dc \uac01\uac01 1\uac1c\uc529, \ub2f9\uc2e0\uc740 \uc784\uc758\uc758 \ubbf8\ub828\uc5d0 \uad11\uae30\uc810\uc744 \ucd94\uac00\ub85c \uc5bb\ub294\ub2e4.","\u3010\uc6b0\uc815\u3011[\ubc1c\uad11:\uacf5\uba85\uc758\uc874]\uc138\uc158 \uc885\ub8cc \uc2dc, \ub300\uc0c1\uc774 \ub2f9\uc2e0\ubcf4\ub2e4 \uc190\uc0c1\ub41c \ud30c\uce20\ub97c \ub354 \ub9ce\uc774 \uac00\uc9c0\uace0 \uc788\ub2e4\uba74, \ub2f9\uc2e0\uc740 \ub300\uc0c1\uacfc \uac19\uc740 \uc218\uc758 \uc190\uc0c1\ub41c \ud30c\uce20\ub97c \uac00\uc9c8 \ub54c\uae4c\uc9c0 \uc790\uc2e0\uc758 \ud30c\uce20\ub97c \uc190\uc0c1\uc2dc\ud0a8\ub2e4.","\u3010\ubcf4\ud638\u3011[\ubc1c\uad11:\uc0c1\uc2dc\ubc00\ucc29]\uc804\ud22c \ub3d9\uc548 \ubbf8\ub828\uc758 \ub300\uc0c1\uacfc \ub2e4\ub978 \uc5d0\ub9ac\uc5b4\uc5d0 \uc788\ub2e4\uba74\u300c\uc774\ub3d9 \uc774\uc678\uc758 \ud6a8\uacfc\ub97c \uac00\uc9c4 \ub9e4\ub274\ubc84\u300d\ub97c \uc120\uc5b8\ud560 \uc218 \uc5c6\ub2e4. \ub610\ud55c\u300c\uc790\uc2e0\uacfc \ubbf8\ub828\uc758 \ub300\uc0c1\u300d\uc774\uc678\ub97c \uc774\ub3d9 \ub9e4\ub274\ubc84\uc758 \ub300\uc0c1\uc73c\ub85c \uc9c0\uc815\ud560 \uc218 \uc5c6\ub2e4.","\u3010\ub3d9\uacbd\u3011[\ubc1c\uad11:\uac70\uc9d3\ub9dd\uc0c1]\uc804\ud22c \ub3d9\uc548 \ubbf8\ub828\uc758 \ub300\uc0c1\uacfc \uac19\uc740 \uc5d0\ub9ac\uc5b4\uc5d0 \uc788\ub2e4\uba74\u300c\uc774\ub3d9 \uc774\uc678\uc758 \ud6a8\uacfc\ub97c \uac00\uc9c4 \ub9e4\ub274\ubc84\u300d\ub97c \uc120\uc5b8\ud560 \uc218 \uc5c6\ub2e4. \ub610\ud55c\u300c\uc790\uc2e0\uacfc \ubbf8\ub828\uc758 \ub300\uc0c1\u300d\uc774\uc678\ub97c \uc774\ub3d9 \ub9e4\ub274\ubc84\uc758 \ub300\uc0c1\uc73c\ub85c \uc9c0\uc815\ud560 \uc218 \uc5c6\ub2e4.","\u3010\uc2e0\ub8b0\u3011[\ubc1c\uad11:\uc758\uc2ec\uc554\uadc0]\ub2f9\uc2e0\uc744 \uc81c\uc678\ud55c \ubaa8\ub4e0 \uc790\ub9e4\uc758 \ucd5c\ub300 \ud589\ub3d9\uce58\uac00 \uac10\uc18c\ud55c\ub2e4(-1)."]},"NMN":{"name":"\uc911\ub9bd\uc790\uc5d0 \ub300\ud55c \ubbf8\ub828\ud45c","type":"1D10","items":["\u3010\uae30\ud53c\u3011[\ubc1c\uad11:\uaca9\ub9ac\uc758\uc2dd]\ub2f9\uc2e0\uc740 \ubbf8\ub828\uc758 \ub300\uc0c1 \ub610\ub294 \uc11c\ubc88\ud2b8\uc640 \uac19\uc740 \uc5d0\ub9ac\uc5b4\uc5d0 \uc788\ub294 \ub3d9\uc548\u300c\uc774\ub3d9 \uc774\uc678\uc758 \ud6a8\uacfc\ub97c \uac00\uc9c4 \ub9e4\ub274\ubc84\u300d\ub97c \uc120\uc5b8\ud560 \uc218 \uc5c6\ub2e4. \ub610\ud55c,\u300c\uc790\uc2e0\uacfc \ubbf8\ub828\uc758 \ub300\uc0c1 \ub610\ub294 \uc11c\ubc88\ud2b8\u300d\ub97c \uc81c\uc678\ud55c \ub2e4\ub978 \ub300\uc0c1\uc740 \uc774\ub3d9 \ub9e4\ub274\ubc84\uc758 \ub300\uc0c1\uc73c\ub85c \uc9c0\uc815\ud560 \uc218 \uc5c6\ub2e4.","\u3010\uc9c8\ud22c\u3011[\ubc1c\uad11:\ubd88\ud611\ud654\uc74c]\ubaa8\ub4e0 \uc790\ub9e4\ub294 \ud589\ub3d9 \ud310\uc815\uc5d0 \uc218\uc815-1\uc744 \ubc1b\ub294\ub2e4.","\u3010\uc758\uc874\u3011[\ubc1c\uad11:\uc720\uc544\ud1f4\ud589]\ucd5c\ub300 \ud589\ub3d9\uce58\uac00 \uac10\uc18c\ud55c\ub2e4(-2).","\u3010\uc5f0\ubbfc\u3011[\ubc1c\uad11:\uacfc\ub2e4\ubab0\uc785]\ub2f9\uc2e0\uc740\u300c\uc11c\ubc88\ud2b8\u300d\uc5d0 \ub300\ud55c \uacf5\uaca9\ud310\uc815\uc758 \uacb0\uacfc\uc5d0 \uc218\uc815-1\uc744 \ubc1b\ub294\ub2e4.","\u3010\uac10\uc0ac\u3011[\ubc1c\uad11:\ubcd1\uc801\ubcf4\ubcf5]\ubc1c\uad11 \uc0c1\ud0dc\uac00 \ub418\uc5c8\uc744 \ub54c, \ub2f9\uc2e0\uc740 \uc784\uc758\uc758 \uae30\ubcf8 \ud30c\uce20 2\uac1c(\uc5c6\ub2e4\uba74 \uac00\uc7a5 \ub0ae\uc740 \ub808\ubca8\uc758 \uac15\ud654 \ud30c\uce20 1\uac1c)\ub97c \uc190\uc0c1\uc2dc\ud0a8\ub2e4.","\u3010\ud68c\ud55c\u3011[\ubc1c\uad11:\uc790\uc5c5\uc790\ub4dd]\ub2f9\uc2e0\uc774 \uc2e4\ud328\ud55c \uacf5\uaca9 \ud310\uc815\uc740 \ubaa8\ub450 \ub2f9\uc2e0 \uc790\uc2e0\uc758 \uc784\uc758\uc758 \ud30c\uce20\uc5d0 \ub300\ubbf8\uc9c0\ub97c \uc785\ud78c\ub2e4.","\u3010\uae30\ub300\u3011[\ubc1c\uad11:\ud76c\ub9dd\uc804\uacb0]\ub2f9\uc2e0\uc740 \uad11\uae30\uc810\uc744 \ucd94\uac00\ud558\uc5ec \uc7ac\uad74\ub9bc\ud560\ub54c, \uadf8 \uacb0\uacfc\uc5d0 -1\uc758 \uc218\uc815\uc744 \ubc1b\ub294\ub2e4(\uc774 \ud6a8\uacfc\ub294 \ub204\uc801\ub41c\ub2e4).","\u3010\ubcf4\ud638\u3011[\ubc1c\uad11:\uc0dd\uc804\ud68c\uadc0]\ub2f9\uc2e0\uc740\u300c\ub808\uae30\uc628\u300d\uc744 \ub9e4\ub274\ubc84\uc758 \ub300\uc0c1\uc73c\ub85c \uc120\ud0dd\ud560 \uc218 \uc5c6\ub2e4.","\u3010\uc874\uacbd\u3011[\ubc1c\uad11:\uc2e0\ud654\uc22d\ubc30]\ub2f9\uc2e0\uc740\u300c\ub2e4\ub978 \uc790\ub9e4\ub4e4\u300d\uc744 \ub9e4\ub274\ubc84\uc758 \ub300\uc0c1\uc73c\ub85c \uc120\ud0dd\ud560 \uc218 \uc5c6\ub2e4.","\u3010\uc2e0\ub8b0\u3011[\ubc1c\uad11:\uc758\uc2ec\uc554\uadc0]\ub2f9\uc2e0\uc744 \uc81c\uc678\ud55c \ubaa8\ub4e0 \uc790\ub9e4\uc758 \ucd5c\ub300 \ud589\ub3d9\uce58\uac00 \uac10\uc18c\ud55c\ub2e4(-1)."]},"NME":{"name":"\uc801\uc5d0 \ub300\ud55c \ubbf8\ub828\ud45c","type":"1D10","items":["\u3010\uacf5\ud3ec\u3011[\ubc1c\uad11:\uc778\uc2dd\uac70\ubd80]\ub2f9\uc2e0\uc740 \ud589\ub3d9 \ud310\uc815 \ubc0f \uad11\uae30 \ud310\uc815\uc758 \uacb0\uacfc\uc5d0 -1\uc758 \uc218\uc815\uce58\ub97c \ubc1b\ub294\ub2e4.","\u3010\uc885\uc18d\u3011[\ubc1c\uad11:\uc870\ubc18\uc720\ub9ac]\ub2f9\uc2e0\uc774 \uc2e4\ud328\ud55c \uacf5\uaca9 \ud310\uc815\uc740 \ubaa8\ub450 \ub300\uc2e4\ud328\ub85c \ucc98\ub9ac\ub41c\ub2e4.","\u3010\ubd88\uc548\u3011[\ubc1c\uad11:\uac70\ub3d9\uc218\uc0c1]\ucd5c\ub300 \ud589\ub3d9\uce58\uac00 \uac10\uc18c\ud55c\ub2e4(-2).","\u3010\uc5f0\ubbfc\u3011[\ubc1c\uad11:\uacfc\ub2e4\ubab0\uc785]\ub2f9\uc2e0\uc740\u300c\uc11c\ubc88\ud2b8\u300d\uc5d0 \ub300\ud55c \uacf5\uaca9\ud310\uc815\uc758 \uacb0\uacfc\uc5d0 \uc218\uc815-1\uc744 \ubc1b\ub294\ub2e4.","\u3010\uc560\uc99d\u3011[\ubc1c\uad11:\ud749\uc560\uc2ec\uc911]\ub2f9\uc2e0\uc740 \uad11\uae30 \ud310\uc815 \ubc0f \uacf5\uaca9 \ud310\uc815\uc5d0\uc11c \ub300\uc131\uacf5\uc744 \uac70\ub458 \ub54c\ub9c8\ub2e4 [\ud310\uc815\uac12 -10] \uac1c\uc758 \uc790\uc2e0\uc758 \ud30c\uce20\ub97c \uc120\ud0dd\ud558\uc5ec \uc190\uc0c1\uc2dc\ud0a8\ub2e4.","\u3010\ud68c\ud55c\u3011[\ubc1c\uad11:\uc790\uc5c5\uc790\ub4dd]\ub2f9\uc2e0\uc774 \uc2e4\ud328\ud55c \uacf5\uaca9 \ud310\uc815\uc740 \ubaa8\ub450 \ub2f9\uc2e0 \uc790\uc2e0\uc758 \uc784\uc758\uc758 \ud30c\uce20\uc5d0 \ub300\ubbf8\uc9c0\ub97c \uc785\ud78c\ub2e4.","\u3010\uacbd\uba78\u3011[\ubc1c\uad11:\uc548\uc911\ubd80\uc7ac]\uac19\uc740 \uc5d0\ub9ac\uc5b4 \ub0b4\uc758 \ub3d9\ub8cc\uac00 \ub2f9\uc2e0\uc5d0\uac8c \uac00\ud558\ub294 \uacf5\uaca9 \ud310\uc815\uc758 \uacb0\uacfc\ub294 \uc218\uc815 +1\uc744 \ubc1b\ub294\ub2e4.","\u3010\ubd84\ub178\u3011[\ubc1c\uad11:\uaca9\uc815\ud3ed\uc8fc]\ub2f9\uc2e0\uc740 \uacf5\uaca9 \ud310\uc815 \ubc0f \uad11\uae30 \ud310\uc815\uc758 \uacb0\uacfc\uc5d0 \uc218\uc815 -1\uc744 \ubc1b\ub294\ub2e4.","\u3010\uc6d0\ud55c\u3011[\ubc1c\uad11:\ubd88\uad6c\ub300\ucc9c]\ub2f9\uc2e0\uc740 \ub3c4\uc8fc \ud310\uc815\uc744 \ud560 \uc218 \uc5c6\ub2e4. \ub2f9\uc2e0\uc774\u300c\uc790\uc2e0\uacfc \ubbf8\ub828\uc758 \ub300\uc0c1\u300d\uc774\uc678\ub97c \ub300\uc0c1\uc73c\ub85c \uc0bc\uc544 \ub9e4\ub274\ubc84\ub97c \uc0ac\uc6a9\ud560 \ub54c, \ud589\ub3d9\uce58 1\uc810\uc744 \ucd94\uac00\ub85c \uac10\uc18c\uc2dc\ucf1c\uc57c \ud55c\ub2e4.","\u3010\uc99d\uc624\u3011[\ubc1c\uad11:\ud754\uc801\ud30c\uad34]\uc774 \ubbf8\ub828\uc774 \ubc1c\uad11\ud560 \ub54c, \ub2f9\uc2e0\uc744 \uc81c\uc678\ud55c \uc790\ub9e4 \uc911 \ud55c \uba85\uc744 \uc120\ud0dd\ud55c\ub2e4. \uadf8 \uc790\ub9e4\ub294 \uc784\uc758\uc758 \ud30c\uce20 2\uac1c\ub97c \uc190\uc0c1\uc2dc\ud0a8\ub2e4."]}}}}}')}}]);